/* ФинМост: браузерный MVP, без банковских подключений и отправки данных. */
(() => {
  'use strict';
  const F = window.FinMost;
  const L = window.FinMostLearning;
  const $ = s => document.querySelector(s);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rub = n => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';
  const num = n => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n);
  const clone = x => JSON.parse(JSON.stringify(x));
  const storageKey = 'finmost-v1';
  let storageAvailable = true, storageWarning = '', toastTimer;
  let state = F.defaultState();
  try {const saved=localStorage.getItem(storageKey);if(saved)state=F.validateState(JSON.parse(saved));}
  catch(e){storageWarning='Сохранённые данные недоступны или повреждены. Открыт учебный пример.';}
  let route = 'overview', lessonFilter='all', businessDraft=clone(state.business), securityScenario='call', securityResult=null;
  let quiz=null, returnFocus=null;
  const main = $('#main'), dialog = $('#dialog');
  const routes = [
    {id:'overview',label:'Обзор',short:'Обзор',icon:'home'},
    {id:'budget',label:'Мой бюджет',short:'Бюджет',icon:'wallet'},
    {id:'business',label:'Платежи бизнеса',short:'Бизнес',icon:'briefcase'},
    {id:'security',label:'Безопасные решения',short:'Защита',icon:'shield'},
    {id:'learn',label:'Практикум',short:'Учиться',icon:'book'},
    {id:'results',label:'Мои результаты',short:'Итоги',icon:'chart'}
  ];
  const paths = {
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
    wallet:'<path d="M20 7H5a2 2 0 0 1 0-4h13v4M4 7v12a2 2 0 0 0 2 2h14V7M16 11h5v6h-5a3 3 0 0 1 0-6Z"/><path d="M16 14h1"/>',
    briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12l9 3 9-3M10 14v3h4v-3"/>',
    shield:'<path d="m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7Z"/><path d="m8 12 3 3 5-6"/>',
    book:'<path d="M12 5v16M3 4l9 2 9-2v15l-9 2-9-2Z"/><path d="m6 9 3 1m6 0 3-1M6 13l3 1m6 0 3-1"/>',
    chart:'<path d="M4 3v18h18M8 16v-4m5 4V7m5 9V4"/>',
    arrow:'<path d="m4 16 6-6 4 4 7-9M15 5h6v6"/>',
    target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="M12 12 21 3M17 3h4v4"/>',
    check:'<path d="m5 12 5 5L20 6"/>',
    bulb:'<path d="M8 17v-2a7 7 0 1 1 8 0v2M8 18h8M9 21h6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'
  };
  const icon = id => '<span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24">'+(paths[id]||paths.target)+'</svg></span>';
  const lessons = {
    budget:{title:'Бюджет, который работает',category:'Личные финансы',tag:'Бюджет',icon:'wallet',time:4,
      desc:'Найдите свободные деньги и проверьте, посилен ли ваш план.',
      body:'<p><b>Начните с фактов.</b> Запишите доход, обязательные платежи, повседневные расходы и платежи по долгам за один и тот же месяц. Если доход меняется, попробуйте несколько сценариев.</p><p>Свободные деньги = доход − расходы. Сумма, которую вы решили откладывать, тоже должна помещаться в бюджет. Например, при доходе 65 000 ₽ и расходах 52 000 ₽ остаётся 13 000 ₽. Если отложить 8 000 ₽, на непредвиденные траты останется 5 000 ₽.</p><p>Если план даёт отрицательный остаток, пересмотрите сумму накоплений или расходы. Новый кредит добавляет будущие обязательства.</p>',
      questions:[
        {q:'Доход — 65 000 ₽, все расходы — 52 000 ₽. Сколько остаётся до накоплений?',a:['8 000 ₽','13 000 ₽','17 000 ₽'],c:1,e:'65 000 − 52 000 = 13 000 ₽. Из этой суммы ещё нужно выделить накопления.'},
        {q:'Свободно 6 000 ₽, а вы планируете откладывать 9 000 ₽. Что показывает такой план?',a:['Дефицит 3 000 ₽. План нужно пересмотреть','Накопления всегда важнее расходов','Можно автоматически считать будущую премию'],c:0,e:'6 000 − 9 000 = −3 000 ₽. План опирается на деньги, которых в бюджете нет.'},
        {q:'Доход нерегулярный. Как проверить устойчивость бюджета?',a:['Учитывать только лучший месяц','Не вести бюджет','Посчитать несколько вариантов дохода'],c:2,e:'Сценарии с разным доходом покажут, выдержит ли план менее удачный месяц.'}]
    },
    reserve:{title:'Подушка без перегрузки',category:'Личные финансы',tag:'Резерв',icon:'target',time:4,
      desc:'Рассчитайте цель резерва и время до неё на своём бюджете.',
      body:'<p><b>Резерв покрывает важные расходы</b> при временном снижении дохода или неожиданной трате. Его размер зависит от вашей ситуации, стабильности доходов и обязательств.</p><p>В тренажёре цель = (обязательные расходы + платежи по долгам) × выбранное число месяцев. Это учебный способ планирования. При 40 000 ₽ важных расходов и горизонте 3 месяца цель составит 120 000 ₽.</p><p>Если уже есть 28 000 ₽, нужно ещё 92 000 ₽. По 8 000 ₽ в месяц — 12 полных ежемесячных пополнений. Расчёт не учитывает проценты, инфляцию и снятия. Держите резерв отдельно от денег на текущие покупки и учитывайте условия доступа к нему.</p>',
      questions:[
        {q:'Важные расходы — 40 000 ₽ в месяц. Цель на 3 месяца равна…',a:['40 000 ₽','80 000 ₽','120 000 ₽'],c:2,e:'40 000 × 3 = 120 000 ₽. Горизонт выбирают под свою ситуацию.'},
        {q:'До цели осталось 92 000 ₽. По 8 000 ₽ в месяц: сколько полных пополнений нужно без процентов?',a:['12','10','8'],c:0,e:'92 000 / 8 000 = 11,5. Округляем вверх: 12 пополнений.'},
        {q:'Какая характеристика особенно важна для финансовой подушки?',a:['Самая высокая возможная доходность','Доступность денег в нужный момент','Вложение всей суммы в один рискованный актив'],c:1,e:'Резерв нужен в непредвиденной ситуации. Важны доступность и сохранность, а условия хранения нужно проверять.'}]
    },
    fraud:{title:'Пауза перед переводом',category:'Безопасность',tag:'Защита',icon:'shield',time:5,
      desc:'Разберите просьбы о кодах, «безопасном счёте» и срочных переводах.',
      body:'<p><b>Пауза даёт время проверить информацию.</b> Просьбы сообщить код из СМС, перевести деньги на «безопасный счёт» или установить удалённый доступ — опасные признаки.</p><p>Завершите сомнительный разговор. Самостоятельно откройте банковское приложение или наберите официальный номер. Не используйте номер или ссылку, которые только что прислал собеседник.</p><p>Новый получатель сам по себе не доказывает мошенничество. Проверьте реквизиты и смысл платежа по независимому каналу. Отсутствие известных признаков тоже не гарантирует безопасность.</p>',
      questions:[
        {q:'«Сотрудник банка» просит код из СМС для защиты счёта. Ваше действие?',a:['Назвать, если он знает имя','Завершить разговор и самому связаться с банком','Переслать код в мессенджер'],c:1,e:'Код нельзя сообщать собеседнику. Контакт с банком нужно начать самостоятельно через официальный канал.'},
        {q:'Звонящий предлагает перевести деньги на «безопасный счёт». Что выбрать?',a:['Сначала перевести небольшую сумму','Попросить красивое удостоверение','Остановиться и проверить информацию в банке'],c:2,e:'«Безопасный счёт» — характерный предлог мошенников. Вид удостоверения и имя собеседника не подтверждают полномочия.'},
        {q:'Тренажёр не нашёл отмеченных признаков риска. Это означает…',a:['Только отсутствие этих признаков, без гарантии безопасности','Банк разрешил перевод','Получатель официально проверен'],c:0,e:'Учебные правила не проверяют человека, реквизиты или историю операций и не заменяют банковский антифрод.'}]
    },
    credit:{title:'Кредит: вся сумма решения',category:'Личные финансы',tag:'Обязательства',icon:'chart',time:4,
      desc:'Отличайте ежемесячный платёж от общей стоимости обязательства.',
      body:'<p><b>Платёж — только часть картины.</b> Перед оформлением сравните сумму, срок, полную стоимость кредита, график, дополнительные услуги и последствия просрочки.</p><p>Простой учебный пример: 24 платежа по 5 000 ₽ — это 120 000 ₽ выплат. Если получили 100 000 ₽ и других расходов нет, разница составит 20 000 ₽. Реальный договор может включать другие условия.</p><p>Проверьте платёж в своём бюджете и сценарий снижения дохода. Одобрение банка не означает, что такой платёж будет комфортен именно вам. Прототип не подбирает кредитные продукты.</p>',
      questions:[
        {q:'24 платежа по 5 000 ₽. Какова их общая сумма?',a:['100 000 ₽','110 000 ₽','120 000 ₽'],c:2,e:'24 × 5 000 = 120 000 ₽. Отдельно нужно проверить другие платежи по договору.'},
        {q:'Что полезно сравнить у кредитных предложений?',a:['Полную стоимость и все условия, а не только платёж','Только цвет карты','Только рекламный слоган'],c:0,e:'Срок, полная стоимость, график и дополнительные услуги влияют на итоговую нагрузку.'},
        {q:'Доход снизился, а обязательный платёж стал непосильным. Что разумно сделать?',a:['Игнорировать уведомления','Заранее связаться с кредитором и обсудить доступные решения','Брать новый заём без расчёта бюджета'],c:1,e:'Своевременное обращение позволяет выяснить доступные варианты. Условия зависят от конкретной ситуации.'}]
    },
    business:{title:'Кассовый разрыв заранее',category:'Малый бизнес',tag:'Бизнес',icon:'briefcase',time:5,
      desc:'Поймите, почему выручка в будущем не оплачивает сегодняшний счёт.',
      body:'<p><b>Прибыль и деньги на счёте отличаются.</b> Клиент может оплатить позже, чем нужно заплатить поставщику. Платёжный календарь учитывает сроки поступлений и выплат.</p><p>Остаток на конец недели = остаток на начало + поступления − платежи. Если было 55 000 ₽, придёт 20 000 ₽, а заплатить нужно 85 000 ₽, получается −10 000 ₽: плану не хватает денег.</p><p>В примере перенос 20 000 ₽ платежа со второй на четвёртую неделю убирает недельный дефицит. Такой перенос возможен только после согласования с контрагентом. Недельная модель может пропустить разрыв внутри недели, поэтому для реальных платежей нужен ежедневный календарь.</p>',
      questions:[
        {q:'На начало недели 55 000 ₽, поступления 20 000 ₽, платежи 85 000 ₽. Итог?',a:['−10 000 ₽','10 000 ₽','55 000 ₽'],c:0,e:'55 000 + 20 000 − 85 000 = −10 000 ₽. В плане возникает кассовый разрыв.'},
        {q:'Чем подтверждается допустимость переноса платежа поставщику?',a:['Положительным графиком','Решением программы','Договорённостью и условиями договора'],c:2,e:'Приложение моделирует последствия. Оно не меняет договор и не согласует перенос с поставщиком.'},
        {q:'Недельные остатки положительные. Возможен ли дефицит во вторник?',a:['Нет, недельная модель видит всё','Да, если платёж раньше поступления внутри недели','Только при нулевой выручке'],c:1,e:'Недельные итоги скрывают порядок событий внутри недели. Для исполнения нужен расчёт по дням.'}]
    },
    data:{title:'Контроль над данными',category:'Безопасность',tag:'Данные',icon:'book',time:3,
      desc:'Разберитесь, где хранится план и что вы передаёте при экспорте.',
      body:'<p><b>В этом прототипе данные хранятся в браузере на устройстве.</b> Сайт не подключается к банковским счетам и не отправляет ваш бюджет на сервер. Другой человек с доступом к профилю браузера может увидеть введённые сведения.</p><p>JSON-отчёт содержит введённые суммы, прогресс и журнал действий. Перед передачей проверьте его содержимое. На общем компьютере используйте только учебные числа.</p><p>Локальное хранение может очиститься вместе с данными браузера. Сохраните резервную копию, если хотите продолжить. Для банковского внедрения потребуются отдельные сервер, аутентификация, управление доступом и проверки безопасности.</p>',
      questions:[
        {q:'Где прототип хранит введённые значения?',a:['Автоматически в ВТБ','В открытом реестре','В хранилище текущего браузера'],c:2,e:'Локальное хранилище связано с браузером и адресом приложения. Оно не синхронизируется между устройствами.'},
        {q:'Что стоит сделать перед передачей JSON-отчёта?',a:['Проверить, какие значения и события в нём есть','Вписать пароли для удобства','Ничего: любые отчёты всегда анонимны'],c:0,e:'Экспорт содержит введённые данные. Пользователь сам выбирает, кому передавать файл.'},
        {q:'Как использовать приложение на общем компьютере?',a:['Ввести реальные реквизиты карты','Оставить учебные значения и при необходимости очистить данные','Сохранить пароль в названии цели'],c:1,e:'Учебных значений достаточно для знакомства. Не вводите реквизиты и секреты.'}]
    }
  };
  Object.assign(lessons,L.lessons);
  const lessonCount=Object.keys(lessons).length;
  const eventNames = {budget_saved:'Сохранён личный план',business_saved:'Сохранён платёжный календарь',risk_checked:'Разобраны признаки риска',safe_decision:'Завершён учебный сценарий безопасности',activity_completed:'Выполнено интерактивное задание',lesson_completed:'Пройден урок',lesson_repeated:'Повторён урок',report_exported:'Скачан отчёт',data_imported:'Восстановлена резервная копия'};
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
  function persist(){
    try {localStorage.setItem(storageKey,JSON.stringify(state));storageAvailable=true;}
    catch(e){storageAvailable=false;}
    $('#save-status').innerHTML=storageAvailable?'<i></i> Данные на устройстве':'Данные только до закрытия';
  }
  function record(type,detail=''){state.events.push({type,time:new Date().toISOString(),detail});if(state.events.length>500)state.events=state.events.slice(-500);persist();}
  function completed(){return Object.keys(state.lessons).length;}
  function points(){return completed()*100;}
  function heading(title,desc,action=''){return '<div class="page-heading"><div><div class="eyebrow">ФИНАНСОВЫЙ НАВИГАТОР</div><h1>'+title+'</h1><p>'+desc+'</p></div>'+action+'</div>';}
  function metric(label,value,foot,ic='wallet',tone=''){return '<div class="metric"><div class="metric-top"><span>'+label+'</span><span class="metric-icon '+tone+'">'+icon(ic)+'</span></div><div class="metric-value">'+value+'</div><div class="metric-foot">'+foot+'</div></div>';}
  function section(title,action='',target='learn'){return '<div class="section-title"><h2>'+title+'</h2>'+(action?'<button class="text-button" data-route="'+target+'">'+action+' <span>→</span></button>':'')+'</div>';}
  function lessonCards(ids){return ids.map(id=>{const l=lessons[id],done=state.lessons[id];return '<button class="lesson-card" data-lesson="'+id+'"><span class="lesson-top"><span class="lesson-icon">'+icon(l.icon)+'</span><span class="chip '+(done?'green':'')+'">'+(done?'Пройден':l.time+' мин')+'</span></span><h3>'+l.title+'</h3><p>'+l.desc+'</p><span class="lesson-bottom"><span>'+(done?'Повторить · '+done.score+'/3':'Начать · +100 баллов')+'</span><span aria-hidden="true">↗</span></span></button>';}).join('');}
  function lineChart(values,labels,baseline,title,goal){
    const width=590,height=222,left=49,right=17,top=18,bottom=37;
    const all=values.concat(baseline||[],goal?[goal]:[]),min=Math.min(0,...all),max=Math.max(1000,...all);
    const lo=min<0?min*1.2:0,hi=max*1.12,range=hi-lo;
    const x=i=>left+i*(width-left-right)/(values.length-1);
    const y=v=>top+(hi-v)/range*(height-top-bottom);
    const pts=v=>v.map((n,i)=>x(i).toFixed(1)+','+y(n).toFixed(1)).join(' ');
    let grid='';
    for(let i=0;i<4;i++){const val=lo+range*i/3,yy=y(val);grid+='<line x1="'+left+'" x2="'+(width-right)+'" y1="'+yy+'" y2="'+yy+'" stroke="#edf0f6"/><text x="'+(left-8)+'" y="'+(yy+3)+'" text-anchor="end" font-size="9" fill="#8c97af">'+Math.round(val/1000)+' т.</text>';}
    if(min<0)grid+='<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(0)+'" y2="'+y(0)+'" stroke="#dca5b1" stroke-dasharray="4 4"/>';
    if(goal)grid+='<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(goal)+'" y2="'+y(goal)+'" stroke="#a9bdc6" stroke-dasharray="4 5"/>';
    const area=left+','+y(0)+' '+pts(values)+' '+x(values.length-1)+','+y(0);
    return '<svg class="chart" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="'+esc(title)+'"><title>'+esc(title)+'</title>'+grid+'<polygon points="'+area+'" fill="#eef2ff"/>'+(baseline?'<polyline points="'+pts(baseline)+'" fill="none" stroke="#a5b1c9" stroke-width="2" stroke-dasharray="5 5"/>':'')+'<polyline points="'+pts(values)+'" fill="none" stroke="#4868e7" stroke-width="2.7" stroke-linejoin="round"/>'+values.map((v,i)=>'<circle cx="'+x(i)+'" cy="'+y(v)+'" r="3.5" fill="'+(v<0?'#cc5770':'#fff')+'" stroke="'+(v<0?'#cc5770':'#4868e7')+'" stroke-width="2"><title>'+esc(labels[i]+': '+rub(v))+'</title></circle><text x="'+x(i)+'" y="'+(height-10)+'" text-anchor="middle" font-size="9" fill="#8c97af">'+esc(labels[i])+'</text>').join('')+'</svg>';
  }
  function reserveChart(){const b=F.budget(state.budget),arr=[0,2,4,6,8,10,12].map(m=>Math.min(b.target,state.budget.reserve+(b.sustainable?m*state.budget.saving:0)));return lineChart(arr,['Сейчас','2 мес','4 мес','6 мес','8 мес','10 мес','12 мес'],null,'План резерва без процентов: '+arr.map(rub).join(', '),b.target);}
  function overview(){
    const b=F.budget(state.budget),biz=F.forecast(state.business),isBiz=state.profile==='business';
    const segments='<div class="segmented" aria-label="Режим обзора"><button data-profile="personal" class="'+(!isBiz?'active':'')+'" aria-pressed="'+(!isBiz)+'">Личные финансы</button><button data-profile="business" class="'+(isBiz?'active':'')+'" aria-pressed="'+isBiz+'">Мой бизнес</button></div>';
    const next=['budget','reserve','fraud','credit','business','data'].find(id=>!state.lessons[id])||'fraud';
    return heading('Хороший день для ваших планов','Деньги под контролем. Следующий шаг — понятен.',segments)+
      '<section class="hero"><div class="hero-copy"><div class="hero-label">'+(isBiz?'ДЛЯ ТЕХ, КТО РАЗВИВАЕТ СВОЁ ДЕЛО':'ВАШ ПЛАН НА БЛИЖАЙШИЕ МЕСЯЦЫ')+'</div><h2>'+(isBiz?'Увидеть кассовый разрыв.<br>До того, как он случится.':'Финансовая уверенность<br>начинается с одного шага')+'</h2><p>'+(isBiz?'Проверьте будущие поступления и платежи. Сравните варианты и сохраните посильный календарь.':'Рассчитайте резерв, проверьте свой бюджет и потренируйтесь принимать безопасные решения.')+'</p><button class="button button-white" data-route="'+(isBiz?'business':'budget')+'">'+(isBiz?'Открыть календарь':'Собрать личный план')+' <span>→</span></button></div><div class="hero-metric"><small>'+(isBiz?'Горизонт планирования':'До цели резерва')+'</small><div class="hero-number">'+(isBiz?'8 недель':b.months===null?'Пересчитаем':b.months===0?'Цель достигнута':b.months+' мес.')+'</div><p>'+(isBiz?'учебный календарь платежей':rub(b.remaining)+' осталось накопить')+'</p><div class="microbar"><i style="width:'+(isBiz?100:b.progress)+'%"></i></div><small>'+(isBiz?'26 октября — 20 декабря 2026':'Готово '+Math.round(b.progress)+'% от цели')+'</small></div></section>'+
      '<div class="metrics">'+(isBiz?
        metric('Деньги на старте',rub(state.business.opening),'Учебный остаток на счёте','briefcase')+metric('Минимум за 8 недель',rub(biz.min),biz.deficit?'<span class="negative">Нужен пересмотр платежей</span>':'<strong>Недельного дефицита нет</strong>','chart',biz.deficit?'orange':'green')+metric('Обучение в действии',completed()+' / '+lessonCount,points()+' учебных баллов','book','orange'):
        metric('Свободно в месяц',rub(b.free),'До выбранных накоплений','wallet')+metric('Ваш резерв',rub(state.budget.reserve),'Цель: '+rub(b.target),'target','green')+metric('Обучение в действии',completed()+' / '+lessonCount,points()+' учебных баллов','book','orange'))+'</div>'+
      '<div class="columns"><section>'+section(isBiz?'План движения денег':'Как растёт ваш резерв','Изменить план',isBiz?'business':'budget')+'<div class="panel"><div class="inline-label"><div><h3>'+(isBiz?'Остаток на конец недели':'Ближе к спокойствию')+'</h3><p class="panel-intro">'+(isBiz?'Расчёт по поступлениям и платежам':'Учебная проекция на 12 месяцев, без процентов')+'</p></div><span class="chip '+(isBiz&&biz.deficit?'orange':'green')+'">'+(isBiz?'План на 8 недель':b.sustainable?'Посильный взнос':'Проверьте взнос')+'</span></div><div class="chart-wrap">'+(isBiz?lineChart(biz.rows.map(r=>r.balance),biz.rows.map(r=>r.label),null,'План недельных остатков, учебные данные'):reserveChart())+'</div><div class="chart-caption"><span>'+(isBiz?'В конце периода: <strong>'+rub(biz.end)+'</strong>':'Ежемесячно: <strong>'+rub(state.budget.saving)+'</strong>')+'</span><span>'+(isBiz?'Дефицит: <strong>'+rub(biz.deficit)+'</strong>':'Цель: <strong>'+rub(b.target)+'</strong>')+'</span></div><div class="insight">'+icon('bulb')+'<div><strong>'+(isBiz?'Момент платежа имеет значение':'Небольшой шаг, который помещается в бюджет')+'</strong><p>'+(isBiz?'В примере можно перенести 20 000 ₽ платежей со второй на четвёртую неделю и сравнить остатки. Перенос требует согласования с поставщиком.':b.available>=0?'После расходов и выбранного взноса остаётся '+rub(b.available)+'. Измените сумму и посмотрите, как поменяется срок достижения цели.':'Взнос превышает свободные деньги на '+rub(-b.available)+'. Откройте бюджет и выберите посильный вариант.')+'</p><button class="text-button" data-route="'+(isBiz?'business':'budget')+'">Проверить вариант <span>→</span></button></div></div></div></section><section>'+section('Следующий полезный шаг')+'<div class="panel"><div class="task"><span class="task-number">01</span><div><b>Проверьте свой план</b><p>Посмотрите, сколько денег остаётся после обязательных расходов.</p><button class="text-button" data-route="budget">Открыть бюджет →</button></div></div><div class="task"><span class="task-number">02</span><div><b>Не спешите с переводом</b><p>Пройдите сценарий со звонком «из службы безопасности».</p><button class="text-button" data-route="security">Разобрать ситуацию →</button></div></div><div class="task"><span class="task-number">03</span><div><b>'+lessons[next].title+'</b><p>'+lessons[next].time+' минуты на знание, которое пригодится в жизни.</p><button class="text-button" data-lesson="'+next+'">Начать урок →</button></div></div></div></section></div>'+
      section('Практика вместо сложных терминов','Весь практикум')+'<div class="lesson-grid">'+lessonCards(['budget','reserve','fraud'])+'</div>';
  }
  function inputField(key,label,value,help='',type='money'){return '<div class="field"><label for="b-'+key+'">'+label+'</label><div class="input-wrap"><input id="b-'+key+'" name="'+key+'" type="number" min="'+(key==='targetMonths'?1:0)+'" max="'+(key==='targetMonths'?12:1000000000)+'" step="'+(key==='targetMonths'?1:1)+'" inputmode="decimal" required value="'+value+'"><span>'+ (type==='money'?'₽':'мес.')+'</span></div>'+(help?'<small>'+help+'</small>':'')+'</div>';}
  function budgetResult(p){
    const b=F.budget(p);
    return '<div class="result-label">После расходов и накоплений</div><div class="result-number '+(b.available<0?'negative':'')+'">'+rub(b.available)+'</div><div class="result-detail">'+(b.available>=0?'Остаётся на непредвиденные траты в этом месяце.':'Плану не хватает денег. Уменьшите взнос или пересмотрите расходы.')+'</div><div class="divider"></div><div class="data-row"><span>Все расходы</span><b>'+rub(b.expenses)+'</b></div><div class="data-row"><span>Свободно до накоплений</span><b>'+rub(b.free)+'</b></div><div class="data-row"><span>Цель резерва</span><b>'+rub(b.target)+'</b></div><div class="data-row"><span>Уже накоплено</span><b>'+rub(p.reserve)+'</b></div><div class="microbar goal-progress"><i style="width:'+b.progress+'%"></i></div><div class="data-row"><span>'+Math.round(b.progress)+'% от цели</span><b>Осталось '+rub(b.remaining)+'</b></div><div class="divider"></div><div class="result-label">Ориентир достижения цели</div><div class="result-number" style="font-size:28px">'+(b.months===0?'Цель достигнута':b.months===null?'Нужен другой взнос':b.months+' мес.')+'</div><p class="explanation">'+(b.months===null?'Срок появится, когда ежемесячный взнос будет больше нуля и поместится в бюджет.':'Без процентов, инфляции и снятий. Последнее пополнение может быть меньше обычного.')+'</p><button class="text-button" data-lesson="reserve">Как устроен расчёт <span>→</span></button>';
  }
  function budgetPage(){const b=state.budget;return heading('Ваш бюджет. Ваш темп.','Измените учебные суммы и найдите план, который вам подходит.')+'<div class="columns"><section class="panel"><h2>План на месяц</h2><p class="panel-intro">Все поля влияют на расчёт. Сохраните изменения, чтобы увидеть их в обзоре.</p><form id="budget-form"><div class="form-grid">'+inputField('income','Доход в месяц',b.income)+inputField('essential','Обязательные расходы',b.essential,'Жильё, питание, транспорт и другие важные траты')+inputField('variable','Необязательные расходы',b.variable,'Досуг, подписки и покупки по желанию')+inputField('debt','Платежи по долгам',b.debt,'Отдельно от обязательных расходов выше')+inputField('reserve','Уже есть в резерве',b.reserve)+inputField('saving','Откладывать в месяц',b.saving)+inputField('targetMonths','Резерв на сколько месяцев',b.targetMonths,'Цель покрывает обязательные расходы и платежи по долгам','months')+'</div><div class="error" id="budget-error" role="alert"></div><div class="form-footer"><button class="button" type="submit">Сохранить мой план <span>✓</span></button><small id="budget-dirty">Сохранённые значения</small></div></form></section><aside class="calc-result" id="budget-result" aria-live="polite">'+budgetResult(b)+'</aside></div><div class="notice spaced">Расчёт помогает сравнить варианты. На общем компьютере используйте учебные числа. Данные остаются в текущем браузере.</div>'+section('Понять своё решение')+'<div class="lesson-grid">'+lessonCards(['budget','reserve','credit'])+'</div>';}
  function businessTable(){const b=F.forecast(businessDraft);return '<table><thead><tr><th scope="col">Неделя с</th><th scope="col" class="num">Поступления, ₽</th><th scope="col" class="num">Платежи, ₽</th><th scope="col" class="num">Остаток, ₽</th></tr></thead><tbody>'+b.rows.map((w,i)=>'<tr><td>'+esc(w.label)+'</td><td class="num"><input class="table-input" type="number" min="0" max="1000000000" step="1" required inputmode="decimal" value="'+w.income+'" data-week="'+i+'" data-kind="income" aria-label="Поступления, неделя с '+esc(w.label)+'"></td><td class="num"><input class="table-input" type="number" min="0" max="1000000000" step="1" required inputmode="decimal" value="'+w.expense+'" data-week="'+i+'" data-kind="expense" aria-label="Платежи, неделя с '+esc(w.label)+'"></td><td class="num '+(w.balance<0?'negative':'')+'" id="balance-'+i+'">'+num(w.balance)+'</td></tr>').join('')+'</tbody></table>';}
  function businessSummary(){const b=F.forecast(businessDraft);return '<span class="chip '+(b.deficit?'red':'green')+'">'+(b.deficit?'В плане есть дефицит':'Недельного дефицита нет')+'</span><h3 class="risk-title">'+(b.deficit?'Не хватает '+rub(b.deficit):'Минимальный остаток '+rub(b.min))+'</h3><p class="explanation">'+(b.deficit?'Впервые остаток становится отрицательным на неделе с '+esc(b.rows[b.firstNegative].label)+'. Измените сроки или суммы и сравните результат.':'Поступлений хватает для указанных недельных итогов. Проверьте порядок платежей внутри недели отдельно.')+'</p><div class="divider"></div><div class="data-row"><span>Всего поступит</span><b>'+rub(b.income)+'</b></div><div class="data-row"><span>Всего платежей</span><b>'+rub(b.expense)+'</b></div><div class="data-row"><span>В конце периода</span><b>'+rub(b.end)+'</b></div>';}
  function businessChart(){const b=F.forecast(businessDraft),base=F.forecast(state.business);return '<div class="chart-legend"><span><i class="legend-dot"></i>Текущий вариант</span><span><i class="legend-dot gray"></i>Сохранённый</span></div>'+lineChart(b.rows.map(w=>w.balance),b.rows.map(w=>w.label),base.rows.map(w=>w.balance),'Недельный остаток: текущий вариант и сохранённый план');}
  function businessPage(){return heading('Деньги бизнеса — по плану','Увидьте дефицит заранее и сравните варианты платежного календаря.','<span class="chip">Дополнительный сценарий · ИП</span>')+'<div class="notice">Учебный пример: 26 октября — 20 декабря 2026 года. Недельная модель не учитывает порядок операций внутри недели. Перенос платежа требует согласования с контрагентом.</div><div class="business-layout"><section class="panel"><div class="inline-label"><div><h2>Календарь на 8 недель</h2><p class="panel-intro">Введите ожидаемые суммы поступлений и платежей.</p></div></div><form id="business-form"><div class="field" style="max-width:240px;margin-bottom:16px"><label for="business-opening">Деньги на начало периода, ₽</label><input id="business-opening" name="opening" type="number" min="0" max="1000000000" step="1" required value="'+businessDraft.opening+'"></div><div id="business-table" class="table-wrap">'+businessTable()+'</div><div class="error" id="business-error" role="alert"></div><div class="form-footer"><button class="button" type="submit">Сохранить календарь <span>✓</span></button><button class="text-button" type="button" data-action="business-revert">Отменить изменения</button></div></form><div class="divider"></div><h3>Проверить «что, если»</h3><p class="explanation">Изменяется только вариант на экране. Сохранение — отдельный шаг.</p><div class="business-actions"><button class="button button-quiet" data-action="shift-payment">Перенести 20 000 ₽<br>со 2-й на 4-ю неделю</button><button class="button button-outline" data-action="delay-receipt">Задержать 20 000 ₽<br>со 2-й на 3-ю неделю</button></div><button class="text-button" data-action="business-example">Вернуть исходный учебный пример</button></section><section class="panel"><div id="business-summary">'+businessSummary()+'</div><div class="spaced"><h3>Остаток на конец недели</h3><div id="business-chart" class="chart-business">'+businessChart()+'</div><div class="insight">'+icon('bulb')+'<div><strong>Выручка и деньги отличаются</strong><p>Дата поступления может быть позже даты платежа. Короткий урок помогает разобраться в кассовом разрыве.</p><button class="text-button" data-lesson="business">Пройти урок →</button></div></div></div></section></div>';}
  const scenarios={
    call:{label:'Звонок из «банка»',recipient:'«Служба безопасности»',amount:25000,story:'Вам звонят якобы из банка: «Счёт под угрозой. Срочно переведите деньги на защищённый счёт и продиктуйте код из СМС».',flags:{safeAccount:true,code:true,remote:false,hurry:true,stranger:true}},
    purchase:{label:'Покупка по ссылке',recipient:'Новый продавец',amount:7500,story:'Продавец предлагает скидку при оплате новому получателю вне площадки. Говорит, что предложение исчезнет через 5 минут.',flags:{safeAccount:false,code:false,remote:false,hurry:true,stranger:true}},
    ordinary:{label:'Знакомый получатель',recipient:'Мастер по договору',amount:4000,story:'Вы сами открыли приложение и собираетесь заплатить знакомому мастеру. Реквизиты сверили с ним по известному номеру. Коды и удалённый доступ никто не просит.',flags:{safeAccount:false,code:false,remote:false,hurry:false,stranger:false}}
  };
  function securityPage(){const s=scenarios[securityScenario];return heading('Пауза, которая помогает','Учебный перевод: найдите признаки риска и выберите следующий шаг.')+'<div class="scenario-options" aria-label="Учебная ситуация">'+Object.entries(scenarios).map(([k,v])=>'<button class="scenario-option '+(k===securityScenario?'active':'')+'" data-scenario="'+k+'" aria-pressed="'+(k===securityScenario)+'">'+v.label+'</button>').join('')+'</div><div class="columns"><section class="panel"><span class="chip orange">Тренажёр · деньги не переводятся</span><h2 style="margin-top:16px">'+s.label+'</h2><p class="explanation">'+s.story+'</p><div class="form-grid"><div class="field"><label for="recipient">Учебный получатель</label><input id="recipient" value="'+esc(s.recipient)+'" maxlength="60"></div><div class="field"><label for="transfer-amount">Учебная сумма, ₽</label><input id="transfer-amount" type="number" min="1" max="1000000000" value="'+s.amount+'" required></div></div><h3 class="hint-heading">Что происходит в этой ситуации?</h3><div class="risk-options">'+[
      ['safeAccount','Просят перевести на «безопасный счёт»'],['code','Просят код из СМС или приложения'],['remote','Предлагают установить удалённый доступ'],['hurry','Торопят и не дают время на проверку'],['stranger','Получатель новый или незнакомый']
    ].map(([k,label])=>'<label class="check-row"><input type="checkbox" name="'+k+'" '+(s.flags[k]?'checked':'')+'><span>'+label+'</span></label>').join('')+'</div><button class="button full-width" data-action="check-risk">Разобрать признаки <span>→</span></button><div class="error" id="risk-error" role="alert"></div></section><section class="panel" id="risk-result" aria-live="polite">'+(securityResult?riskResult(securityResult):'<div class="empty-state"><div class="lesson-icon">'+icon('shield')+'</div><h3>Сначала — разобраться</h3><p class="explanation">Выберите ситуацию, проверьте отмеченные признаки и посмотрите объяснение.</p></div><div class="notice">Тренажёр объясняет заданные признаки по открытым правилам. Он не проверяет получателя и не заменяет антифрод банка.</div>')+'</section></div>'+section('Закрепить привычку')+'<div class="lesson-grid">'+lessonCards(['fraud','data','budget'])+'</div>';}
  function riskResult(r){let label,title,text;if(r.level==='high'){label='Есть опасные признаки';title='Остановитесь и проверьте';text='Завершите разговор. Свяжитесь с банком самостоятельно через официальное приложение или известный номер. Не сообщайте коды.';}else if(r.level==='review'){label='Нужна проверка';title='Возьмите паузу';text='Уточните реквизиты и назначение платежа по независимому каналу. Срочность и новый получатель требуют внимания.';}else{label='Заданные признаки не найдены';title='Проверьте детали самостоятельно';text='Отсутствие отмеченных признаков не гарантирует безопасность. Перепроверьте получателя, сумму и назначение.';}return '<span class="chip '+(r.level==='high'?'red':r.level==='review'?'orange':'green')+'">'+label+'</span><h2 class="risk-title">'+title+'</h2><p class="explanation">'+text+'</p>'+(r.reasons.length?'<ul class="reason-list">'+r.reasons.map(t=>'<li>'+t+'</li>').join('')+'</ul>':'<p class="explanation">В выбранной ситуации не отмечены просьбы о кодах, «безопасном счёте», удалённом доступе, спешка и новый получатель.</p>')+'<div class="divider"></div><div class="button-row"><button class="button '+(r.level==='clear'?'':'button-quiet')+'" data-action="safe-decision">'+(r.level==='clear'?'Завершить учебный сценарий':'Отложить учебный перевод')+'</button><button class="text-button" data-lesson="fraud">Пройти урок →</button></div><p class="explanation tiny">Никаких платёжных распоряжений приложение не создаёт. Результат относится только к выбранным признакам.</p>';}
  function learnPage(){
    const ids=Object.keys(lessons),filtered=ids.filter(id=>lessonFilter==='all'||lessonFilter==='done'&&state.lessons[id]||lessonFilter==='todo'&&!state.lessons[id]||lessonFilter==='foundations'&&lessons[id].activity||lessonFilter==='practice'&&!lessons[id].activity);
    const foundations=filtered.filter(id=>lessons[id].activity),practice=filtered.filter(id=>!lessons[id].activity);
    return heading('Понять деньги. Управлять увереннее.','Откуда взялись деньги, как они работают и что меняется в вашем кошельке.')+'<section class="progress-banner"><div><h2>Разобраться → попробовать → закрепить</h2><p>Четыре интерактивных урока об устройстве денег и шесть уроков о повседневных решениях. По 100 баллов за первое завершение.</p></div><div class="nowrap"><strong>'+completed()+'</strong><span class="small"> / '+lessonCount+' уроков</span></div></section><div class="filters" aria-label="Фильтр уроков">'+[['all','Все уроки'],['foundations','Как устроены деньги'],['practice','Практические навыки'],['todo','Ещё не пройдены'],['done','Пройдены']].map(([id,label])=>'<button class="filter '+(lessonFilter===id?'active':'')+'" data-filter="'+id+'" aria-pressed="'+(lessonFilter===id)+'">'+label+'</button>').join('')+'</div>'+(foundations.length?'<section class="learning-group"><div class="learning-group-heading"><div><span class="eyebrow">ОТ ОСНОВ К СВОЕМУ РЕШЕНИЮ</span><h2>Как устроены деньги</h2></div><span class="chip">Интерактивные задания</span></div><div class="lesson-grid all-lessons">'+lessonCards(foundations)+'</div></section>':'')+(practice.length?'<section class="learning-group"><div class="learning-group-heading"><div><span class="eyebrow">ПРИМЕНИТЬ В ЖИЗНИ</span><h2>Практические навыки</h2></div></div><div class="lesson-grid all-lessons">'+lessonCards(practice)+'</div></section>':'')+(filtered.length?'':'<div class="panel empty-state"><h3>Здесь пока пусто</h3><p class="explanation">Выберите другой фильтр или начните первый урок.</p><button class="button" data-filter="all">Показать все уроки</button></div>');
  }
  function resultsPage(){const score=Object.values(state.lessons).reduce((s,l)=>s+l.score,0),events=state.events.slice().reverse().slice(0,50),savedBudgets=state.events.filter(e=>e.type==='budget_saved').length,savedBiz=state.events.filter(e=>e.type==='business_saved').length;return heading('Ваши решения и результаты','Здесь только действия в этом браузере. Это не статистика банковских клиентов.','<button class="button button-outline" data-action="export-csv">Журнал в CSV ↗</button>')+'<div class="metrics">'+metric('Учебные баллы',num(points()),'По 100 за каждый завершённый урок','target')+metric('Верных ответов',score+' / '+completed()*3,'Лучший результат каждого урока','book','green')+metric('Разборов безопасности',num(state.safetyRuns),'Завершено сценариев: '+num(state.safeDecisions),'shield','orange')+'</div><div class="report-grid"><section class="panel"><h2>Прогресс в практикуме</h2><p class="panel-intro">Баллы показывают участие, ответы — усвоение материала.</p>'+Object.entries(lessons).map(([id,l])=>'<div class="report-lesson"><span class="chip '+(state.lessons[id]?'green':'')+'">'+(state.lessons[id]?'✓':'○')+'</span><button class="text-button" data-lesson="'+id+'">'+l.title+'</button><span>'+(state.lessons[id]?state.lessons[id].score+'/3':'Не пройден')+'</span></div>').join('')+'</section><section class="panel"><h2>Последние действия</h2><p class="panel-intro">До 500 событий на устройстве. Здесь показаны последние 50.</p><div class="event-list">'+(events.length?events.map(e=>'<div class="event-row"><span class="event-dot"></span><div><strong>'+esc(eventNames[e.type]||e.type)+'</strong><small>'+esc(new Date(e.time).toLocaleString('ru-RU'))+(e.detail?' · '+esc(e.detail):'')+'</small></div></div>').join(''):'<div class="empty-state"><p class="explanation">Сохраните план или пройдите урок — появится первое действие.</p></div>')+'</div></section><section class="panel"><h2>Планы в действии</h2><div class="data-row"><span>Сохранений личного бюджета</span><b>'+savedBudgets+'</b></div><div class="data-row"><span>Сохранений календаря ИП</span><b>'+savedBiz+'</b></div><div class="data-row"><span>Остаток личного бюджета</span><b>'+rub(F.budget(state.budget).available)+'</b></div><p class="explanation">Эти счётчики подтверждают использование функций на этом устройстве. Изменение знаний, удержания и обращений в поддержку нужно измерять отдельно в пилоте.</p></section><section class="panel"><h2>Управление данными</h2><p class="panel-intro">Отчёт JSON — это также резервная копия для продолжения работы.</p><div class="settings-row"><span>План, прогресс и журнал</span><button class="button button-outline button-small" data-action="export">Скачать JSON</button></div><div class="settings-row"><span>Восстановить из своего JSON</span><button class="button button-outline button-small" data-action="import">Выбрать файл</button></div><div class="settings-row"><span>Вернуть учебные значения</span><button class="button button-danger button-small" data-action="reset">Сбросить</button></div><div class="storage-note">Реальные реквизиты и пароли вводить не нужно. Данные не синхронизируются между устройствами.</div></section></div>';}
  function render(){
    document.body.classList.toggle('large',state.largeText);
    const nav=$('#nav');nav.innerHTML=routes.map(r=>'<button class="nav-button '+(route===r.id?'active':'')+'" data-route="'+r.id+'" '+(route===r.id?'aria-current="page"':'')+'>'+icon(r.icon)+'<span class="desktop-label">'+r.label+'</span>'+(r.id==='business'?'<span class="nav-badge">ИП</span>':'')+'</button>').join('');
    if(window.matchMedia('(max-width:740px)').matches)nav.querySelectorAll('.desktop-label').forEach((el,i)=>el.textContent=routes[i].short);
    $('#crumb').textContent=routes.find(r=>r.id===route).label;
    main.innerHTML=({overview, budget:budgetPage,business:businessPage,security:securityPage,learn:learnPage,results:resultsPage})[route]();
    document.title=routes.find(r=>r.id===route).label+' — ФинМост';
  }
  function navigate(id,focus=true){if(!routes.some(r=>r.id===id))id='overview';if(route!==id){businessDraft=clone(state.business);securityResult=null;}route=id;if(location.hash!=='#'+id)history.replaceState(null,'','#'+id);render();if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
  function openDialog(html){returnFocus=document.activeElement;$('#dialog-content').innerHTML=html;dialog.showModal();dialog.querySelector('button')?.focus();}
  function closeDialog(){dialog.close();quiz=null;returnFocus?.isConnected&&returnFocus.focus();}
  const dialogHead=(title,eyebrow='')=>'<div class="dialog-head"><div>'+(eyebrow?'<div class="eyebrow">'+eyebrow+'</div>':'')+'<h2 id="dialog-title">'+title+'</h2></div><button class="close" data-action="close" aria-label="Закрыть">×</button></div>';
  function lessonSources(l){return '<details class="lesson-sources"><summary>Источники и границы модели</summary>'+(l.model?'<p>'+l.model+'</p>':'')+'<ul>'+l.sources.map(s=>'<li><a href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+s.title+' ↗</a></li>').join('')+'</ul><p>Материалы проверены 26 октября 2026 года. Пояснения и задания подготовлены для ФинМоста.</p></details>';}
  function lessonStage(stage){
    if(!quiz||!quiz.activity)return;
    const l=lessons[quiz.id],a=quiz.activity;
    $('#dialog-content').innerHTML=dialogHead(l.title,l.category+' · '+l.time+' МИНУТ')+'<div class="lesson-stages" aria-label="Этап урока"><button data-lesson-stage="read" '+(stage==='read'?'aria-current="step"':'')+'>1. Разобраться</button><button data-lesson-stage="practice" '+(stage==='practice'?'aria-current="step"':'')+'>2. Попробовать</button><span>3. Закрепить</span></div>'+(stage==='read'?'<div class="dialog-body">'+l.body+'</div>'+lessonSources(l)+'<div class="dialog-footer"><span class="small muted">Без спешки: можно вернуться к объяснению</span><button class="button" data-lesson-stage="practice">Перейти к заданию →</button></div>':'<div id="lesson-activity" class="lesson-activity"></div>'+lessonSources(l)+'<div class="dialog-footer"><span id="activity-status" class="small muted"></span><button class="button" data-action="quiz-start" '+(a.done?'':'disabled')+'>Проверить себя →</button></div>');
    if(stage==='practice')renderActivity();
  }
  function priceResults(a){
    const p=L.purchasingPower(10000,a.inflation,a.growth,a.years),direction=p.change>0.000001?'выше':p.change<-.000001?'ниже':'та же';
    const amounts=Array.from({length:a.years+1},(_,i)=>10000*(1+a.growth/100)**i),prices=Array.from({length:a.years+1},(_,i)=>10000*(1+a.inflation/100)**i);
    return '<div class="price-metrics"><div><small>Будущая сумма</small><strong>'+rub(p.nominal)+'</strong><span>Номинальные рубли</span></div><div><small>В сегодняшних ценах</small><strong>'+rub(p.real)+'</strong><span>'+p.baskets.toLocaleString('ru-RU',{maximumFractionDigits:2})+' — доступно корзин вместо 10</span></div></div><p class="price-verdict">Покупательная способность '+direction+(direction==='та же'?'':': '+p.change.toLocaleString('ru-RU',{maximumFractionDigits:2})+'%')+'. Корзина будет стоить '+rub(p.basket)+'.</p><div class="chart-legend"><span><i class="legend-dot"></i>Сбережения</span><span><i class="legend-dot gray"></i>Цена 10 корзин</span></div>'+lineChart(amounts,amounts.map((_,i)=>i+' г.'),prices,'Сумма сбережений и стоимость десяти одинаковых корзин в рублях')+'<p class="explanation tiny">Если сбережения отстают от цены тех же 10 корзин, на них можно купить меньше. Округление — только на экране.</p>';
  }
  function activityView(){
    const a=quiz.activity,l=lessons[quiz.id];
    let content='';
    if(l.activity==='roles'){
      const r=L.roleRounds[a.step];
      content='<div class="eyebrow">СИТУАЦИЯ '+(a.step+1)+' ИЗ 3</div><h3>Какая функция денег работает?</h3><p class="activity-prompt">'+r.text+'</p><div class="activity-choices">'+L.roleOptions.map((v,i)=>'<button class="answer '+(a.accepted&&i===r.correct?'correct':'')+'" data-activity-choice="'+i+'" '+(a.accepted?'disabled':'')+'>'+v+'</button>').join('')+'</div>';
    }else if(l.activity==='timeline'){
      content='<div class="eyebrow">МАШИНА ВРЕМЕНИ</div><h3>Соберите четыре события</h3><p class="activity-prompt">Расположите примеры от самого раннего к позднему. Используйте стрелки; перетаскивание не требуется.</p><ol class="timeline-sort">'+a.order.map((id,i)=>{const t=L.timeline.find(t=>t.id===id);return '<li><span class="timeline-position">'+(i+1)+'</span><div><strong>'+t.title+'</strong>'+(a.done?'<small>'+t.date+'</small><p>'+t.text+'</p>':'')+'</div><div class="timeline-arrows"><button class="icon-button" data-activity-move="-1" data-index="'+i+'" aria-label="Поднять: '+t.title+'" '+(i===0||a.done?'disabled':'')+'>↑</button><button class="icon-button" data-activity-move="1" data-index="'+i+'" aria-label="Опустить: '+t.title+'" '+(i===a.order.length-1||a.done?'disabled':'')+'>↓</button></div></li>';}).join('')+'</ol>'+(a.done?'':'<button class="button button-quiet" data-action="timeline-check">Проверить порядок</button>');
    }else if(l.activity==='flows'){
      const r=L.flowSteps[a.step];
      content='<div class="eyebrow">ПЛАТЁЖ '+(a.step+1)+' ИЗ 4</div><h3>Денежный круг</h3><div class="economy-accounts">'+Object.entries(a.accounts).map(([id,v])=>'<div class="economy-account '+(a.accepted&&id===r.to?'receiving':'')+'"><small>'+L.accountNames[id]+'</small><strong>'+rub(v)+'</strong></div>').join('')+'</div><p class="economy-total">Всего в модели: <b>'+rub(Object.values(a.accounts).reduce((s,v)=>s+v,0))+'</b></p><p class="activity-prompt">'+r.text+'</p><div class="activity-choices">'+Object.keys(L.accountNames).filter(id=>id!==r.from).map(id=>'<button class="answer '+(a.accepted&&id===r.to?'correct':'')+'" data-activity-choice="'+id+'" '+(a.accepted?'disabled':'')+'>'+L.accountNames[id]+'</button>').join('')+'</div><p class="explanation tiny">Четыре участника, только заданные переводы. Это не модель изменения денежной массы страны.</p>';
    }else if(l.activity==='prices'){
      content='<div class="eyebrow">ЛАБОРАТОРИЯ ЦЕН</div><h3>Рублей больше. А возможностей?</h3><p class="activity-prompt">Начните с 10 000 ₽. Зафиксируйте два наблюдения: когда рост сбережений ниже роста цен и когда выше.</p><div class="price-controls">'+[['inflation','Годовой рост цен',0,25,'%'],['growth','Годовой рост сбережений',0,25,'%'],['years','Срок, лет',1,10,'']].map(([id,label,min,max,unit])=>'<div class="range-field"><label for="price-'+id+'">'+label+' <output id="price-'+id+'-value" for="price-'+id+'">'+a[id]+' '+unit+'</output></label><input id="price-'+id+'" type="range" min="'+min+'" max="'+max+'" step="1" value="'+a[id]+'" data-price-param="'+id+'"><div class="range-ends"><span>'+min+' '+unit+'</span><span>'+max+' '+unit+'</span></div></div>').join('')+'</div><div id="price-results">'+priceResults(a)+'</div><div class="observation-list"><span class="chip '+(a.observed.loss?'green':'')+'">'+(a.observed.loss?'✓':'○')+' Сбережения отстают</span><span class="chip '+(a.observed.gain?'green':'')+'">'+(a.observed.gain?'✓':'○')+' Сбережения опережают</span></div><button class="button button-quiet" data-action="prices-observe">Зафиксировать наблюдение</button><p class="explanation tiny">Темпы заданы для эксперимента. Это не прогноз инфляции и не условия вклада.</p>';
    }
    return content+'<div class="activity-feedback '+(a.error?'is-error':'')+'" id="activity-feedback" role="status" tabindex="-1">'+(a.message||'Выберите действие — объяснение появится здесь.')+'</div>'+(a.accepted&&!a.done?'<button class="button button-quiet" data-action="activity-next">Следующий '+(l.activity==='flows'?'платёж':'пример')+' →</button>':'')+(a.done?'<div class="activity-done">✓ Задание выполнено. Теперь закрепите результат тремя вопросами.</div>':'');
  }
  function renderActivity(focus=false){
    const a=quiz.activity;
    if(a.done&&!a.logged){a.logged=true;record('activity_completed',lessons[quiz.id].title);}
    $('#lesson-activity').innerHTML=activityView();
    $('#activity-status').textContent=a.done?'3 вопроса · '+(state.lessons[quiz.id]?'повторение без новых баллов':'+100 учебных баллов'):'Сначала выполните задание. Баллы — после трёх вопросов.';
    dialog.querySelector('[data-action="quiz-start"]').disabled=!a.done;
    if(focus)$('#activity-feedback').focus({preventScroll:true});
  }
  function activityChoice(value){
    if(!quiz||!quiz.activity||quiz.activity.accepted)return;
    const a=quiz.activity,type=lessons[quiz.id].activity;
    if(type!=='roles'&&type!=='flows')return;
    const r=(type==='roles'?L.roleRounds:L.flowSteps)[a.step];
    const correct=type==='roles'?Number(value)===r.correct:value===r.to;
    a.error=!correct;
    if(!correct){a.message=type==='roles'?'Попробуйте ещё раз: подумайте, сравниваем ли мы цены, совершаем покупку или сохраняем деньги.':'Попробуйте ещё раз: выберите участника, который получает оплату за указанный товар, труд или обязательство.';}
    else{
      if(type==='flows')a.accounts=L.applyFlow(a.accounts,a.step,value);
      a.accepted=true;a.message='Верно. '+r.explanation;
      if(a.step===(type==='roles'?L.roleRounds:L.flowSteps).length-1)a.done=true;
    }
    renderActivity(true);
  }
  function openLesson(id){
    if(!lessons[id])return;const l=lessons[id];
    quiz={id,index:0,selected:null,checked:false,score:0};
    if(l.activity){
      quiz.activity={step:0,accepted:false,done:false,message:'',error:false,logged:false,order:['russia','sbp','coins','china'],accounts:{...L.flowAccounts},inflation:10,growth:5,years:3,observed:{loss:false,gain:false}};
      openDialog('');lessonStage('read');dialog.querySelector('[data-lesson-stage="practice"]').focus();
    }else openDialog(dialogHead(l.title,l.category+' · '+l.time+' МИНУТ')+'<div class="dialog-body">'+l.body+'</div><div class="dialog-footer"><span class="small muted">3 вопроса · '+(state.lessons[id]?'повторение без новых баллов':'+100 учебных баллов')+'</span><button class="button" data-action="quiz-start">Проверить себя →</button></div>');
  }
  function renderQuestion(){const l=lessons[quiz.id],q=l.questions[quiz.index];$('#dialog-content').innerHTML=dialogHead(l.title,'ВОПРОС '+(quiz.index+1)+' ИЗ 3')+'<div class="quiz-progress">'+l.questions.map((_,i)=>'<i class="'+(i<=quiz.index?'done':'')+'"></i>').join('')+'</div><div class="question" id="question-title">'+q.q+'</div><div class="answer-list" role="group" aria-labelledby="question-title">'+q.a.map((a,i)=>'<button class="answer '+(quiz.checked?(i===q.c?'correct':i===quiz.selected?'wrong':''):i===quiz.selected?'selected':'')+'" data-answer="'+i+'" aria-pressed="'+(i===quiz.selected)+'" '+(quiz.checked?'disabled':'')+'><span class="answer-number">'+(i+1)+'</span><span>'+a+'</span></button>').join('')+'</div>'+(quiz.checked?'<div class="quiz-feedback" role="status"><b>'+(quiz.selected===q.c?'Верно.':'Разберём ответ.')+'</b> '+q.e+'</div>':'')+'<div class="dialog-footer"><span class="small muted">Выберите один ответ</span><button class="button" data-action="quiz-next" '+(quiz.selected===null?'disabled':'')+'>'+(quiz.checked?(quiz.index===2?'Посмотреть результат':'Следующий вопрос →'):'Проверить ответ')+'</button></div>';}
  function quizNext(){if(!quiz||quiz.selected===null)return;const l=lessons[quiz.id];if(!quiz.checked){quiz.checked=true;if(quiz.selected===l.questions[quiz.index].c)quiz.score++;renderQuestion();dialog.querySelector('[data-action="quiz-next"]').focus();return;}if(quiz.index<2){quiz.index++;quiz.selected=null;quiz.checked=false;renderQuestion();dialog.querySelector('.answer').focus();return;}const result=F.completeLesson(state,quiz.id,quiz.score,new Date().toISOString());record(result.first?'lesson_completed':'lesson_repeated',l.title+' · '+quiz.score+'/3');render();$('#dialog-content').innerHTML=dialogHead('Полезный шаг сделан')+'<div class="quiz-summary"><div class="eyebrow">РЕЗУЛЬТАТ УРОКА</div><div class="big-stat">'+quiz.score+' <span style="font-size:24px;color:#93a0bd">/ 3</span></div><h3>'+ (quiz.score===3?'Всё верно!':quiz.score>=1?'Есть что закрепить':'Попробуйте ещё раз')+'</h3><p>'+ (result.first?'+100 баллов за первое завершение. ':'Повторение без дополнительных баллов. ')+'Лучший результат сохраняется.<br>Баллы учебные и не являются денежным вознаграждением.</p></div><div class="dialog-footer"><button class="text-button" data-lesson="'+quiz.id+'">Повторить урок</button><button class="button" data-action="quiz-finish">К моим результатам →</button></div>';}
  function guide(){openDialog(dialogHead('Пять минут с ФинМостом','ДЕМО-СЦЕНАРИЙ')+'<div class="dialog-body"><p>Все значения учебные. Можно менять суммы, сохранять планы и проходить уроки.</p></div>'+[
    ['budget','Личный план','Измените взнос с 8 000 до 10 000 ₽. Срок станет 10 месяцев.'],
    ['security','Безопасный выбор','Разберите звонок из «банка» и отложите перевод.'],
    ['business','Календарь ИП','Перенесите 20 000 ₽ со второй на четвёртую неделю.'],
    ['learn','Короткая практика','Пройдите урок и проверьте три ответа.'],
    ['results','Проверяемый результат','Посмотрите журнал и скачайте свой отчёт.']
  ].map(([id,t,d],i)=>'<div class="guide-step"><span class="task-number">0'+(i+1)+'</span><div><strong>'+t+'</strong><p>'+d+'</p></div><button class="button button-outline button-small" data-guide="'+id+'">Открыть →</button></div>').join(''));}
  function about(){openDialog(dialogHead('ФинМост','АКАДЕМИЯ ФИНТЕХА 2026')+'<div class="dialog-body"><p>Финансовый навигатор с обучением через решения. Основной сценарий — личный бюджет и безопасные действия молодого клиента. Дополнительный сценарий — платёжный календарь начинающего предпринимателя.</p><p><b>Что работает:</b> расчёты, сравнение вариантов, 10 уроков с 30 вопросами, включая 4 интерактивных задания, прогресс, журнал и резервные копии. Все объяснения формируются по открытым правилам.</p><p><b>Границы версии:</b> банковских API, реальных переводов, серверной аналитики и генеративного ИИ нет. Данные локальные, пример бизнеса зафиксирован на октябрь–декабрь 2026 года. Для банковского пилота потребуются интеграция, аутентификация и проверки ИБ.</p><p>Кейс: «Финтех без границ: банк будущего для бизнеса и клиентов». Прототип не является официальным сервисом ВТБ.</p><p><a href="https://fintechacademy.ru/task-1" target="_blank" rel="noopener noreferrer">Условия трека</a> · <a href="https://fincult.info/" target="_blank" rel="noopener noreferrer">Финансовая культура Банка России</a></p></div><div class="dialog-footer"><button class="text-button" data-action="guide-reopen">Демо-сценарий →</button><button class="button" data-action="close">Понятно</button></div>');}
  function readBudget(){const form=$('#budget-form'),p={};for(const [k,v] of new FormData(form))p[k]=v;F.budget(p);for(const k of Object.keys(p))p[k]=Number(p[k]);return p;}
  function updateBusiness(){const form=$('#business-form');if(!form.reportValidity())return false;businessDraft.opening=F.numeric($('#business-opening').value,'деньги на начало');form.querySelectorAll('[data-week]').forEach(input=>{businessDraft.weeks[Number(input.dataset.week)][input.dataset.kind]=F.numeric(input.value,'сумма');});const calc=F.forecast(businessDraft);calc.rows.forEach((row,i)=>{const cell=$('#balance-'+i);cell.textContent=num(row.balance);cell.classList.toggle('negative',row.balance<0);});$('#business-summary').innerHTML=businessSummary();$('#business-chart').innerHTML=businessChart();$('#business-error').textContent='';return true;}
  function saveFile(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportJson(){record('report_exported','JSON, бюджет и прогресс');const payload={...clone(state),exportedAt:new Date().toISOString(),app:'ФинМост',notice:'Содержит введённые суммы и журнал. Перед передачей проверьте содержимое.',calculations:{budget:F.budget(state.budget),business:F.forecast(state.business)},metrics:{completedLessons:completed(),points:points(),localOnly:true}};saveFile('finmost-report.json',JSON.stringify(payload,null,2),'application/json;charset=utf-8');toast('Отчёт JSON скачан. Он также подходит для восстановления.');if(route==='results')render();}
  function exportCsv(){const safe=s=>{let t=String(s);if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const rows=[['Время ISO','Событие','Подробности'],...state.events.map(e=>[e.time,eventNames[e.type]||e.type,e.detail])];saveFile('finmost-events.csv','\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Журнал действий скачан в CSV');}
  function checkRisk(){const amount=$('#transfer-amount');if(!amount.reportValidity())return;try{F.numeric(amount.value,'сумма',1);const flags={};Object.keys(F.riskRules).forEach(k=>flags[k]=!!document.querySelector('input[name="'+k+'"]').checked);securityResult={...F.risk(flags),handled:false};state.safetyRuns++;record('risk_checked',scenarios[securityScenario].label+' · '+({high:'опасные признаки',review:'нужна проверка',clear:'заданные признаки не найдены'}[securityResult.level]));$('#risk-result').innerHTML=riskResult(securityResult);}catch(e){$('#risk-error').textContent=e.message;}}
  function applyBusinessScenario(kind){try{if(!updateBusiness())return;businessDraft=kind==='shift'?F.shiftPayment(businessDraft,1,3,20000):F.delayReceipt(businessDraft,1,2,20000);render();toast(kind==='shift'?'Вариант: 20 000 ₽ перенесены. Проверьте график и сохраните.':'Вариант: поступление 20 000 ₽ задержано на неделю.');}catch(e){$('#business-error').textContent=e.message;}}
  document.addEventListener('click',event=>{
    const el=event.target.closest('button,[data-route]');if(!el)return;
    if(el.dataset.route){navigate(el.dataset.route);return;}
    if(el.dataset.profile){state.profile=el.dataset.profile;persist();render();return;}
    if(el.dataset.lesson){if(dialog.open)dialog.close();openLesson(el.dataset.lesson);return;}
    if(el.dataset.lessonStage){lessonStage(el.dataset.lessonStage);dialog.querySelector('[data-lesson-stage="'+el.dataset.lessonStage+'"]').focus();return;}
    if(el.dataset.activityChoice!==undefined){activityChoice(el.dataset.activityChoice);return;}
    if(el.dataset.activityMove!==undefined&&quiz?.activity&&!quiz.activity.done){
      const a=quiz.activity,from=Number(el.dataset.index),to=from+Number(el.dataset.activityMove);
      if(lessons[quiz.id].activity==='timeline'&&to>=0&&to<a.order.length){[a.order[from],a.order[to]]=[a.order[to],a.order[from]];a.message='Порядок изменён. Проверьте, какое событие было раньше.';a.error=false;renderActivity();dialog.querySelector('[data-index="'+to+'"][data-activity-move="'+el.dataset.activityMove+'"]')?.focus({preventScroll:true});}return;
    }
    if(el.dataset.filter){lessonFilter=el.dataset.filter;render();return;}
    if(el.dataset.scenario){securityScenario=el.dataset.scenario;securityResult=null;render();return;}
    if(el.dataset.guide){closeDialog();navigate(el.dataset.guide);return;}
    if(el.dataset.answer!==undefined&&quiz&&!quiz.checked){quiz.selected=Number(el.dataset.answer);renderQuestion();dialog.querySelector('[data-answer="'+quiz.selected+'"]').focus();return;}
    const action=el.dataset.action;
    if(action==='close')closeDialog();
    else if(action==='guide')guide();
    else if(action==='guide-reopen'){dialog.close();guide();}
    else if(action==='about')about();
    else if(action==='large'){state.largeText=!state.largeText;persist();document.body.classList.toggle('large',state.largeText);toast(state.largeText?'Крупный текст включён':'Обычный размер текста');}
    else if(action==='quiz-start'){if(quiz&&(!quiz.activity||quiz.activity.done))renderQuestion();}
    else if(action==='activity-next'&&quiz?.activity?.accepted&&!quiz.activity.done){quiz.activity.step++;quiz.activity.accepted=false;quiz.activity.message='';quiz.activity.error=false;renderActivity();dialog.querySelector('[data-activity-choice]')?.focus({preventScroll:true});}
    else if(action==='timeline-check'&&quiz?.activity&&lessons[quiz.id].activity==='timeline'){
      const a=quiz.activity;a.done=L.timelineCorrect(a.order);a.error=!a.done;
      const count=a.order.filter((id,i)=>id===L.timeline[i].id).length;
      a.message=a.done?'Верно: VII век до н. э. → 1375 → 1769 → 2019. Формы денег и способы платежа могут сосуществовать.':'На своих местах '+count+' из 4 событий. Вспомните ориентиры из объяснения: ранние монеты, китайский бумажный знак, российские ассигнации, СБП.';renderActivity(true);
    }
    else if(action==='prices-observe'&&quiz?.activity&&lessons[quiz.id].activity==='prices'){
      const a=quiz.activity,delta=a.growth-a.inflation;
      if(delta<0)a.observed.loss=true;if(delta>0)a.observed.gain=true;
      a.done=a.observed.loss&&a.observed.gain;a.error=false;
      a.message=delta===0?'Темпы равны: в нашей модели покупательная способность сохраняется. Для задания сравните ещё два разных темпа.':delta<0?'Сбережения отстают: номинальная сумма может расти, а доступных корзин становится меньше. Теперь проверьте обратное соотношение.':'Сбережения опережают: покупательная способность в этой модели растёт. Проверьте также случай, когда цены растут быстрее.';
      if(a.done)a.message='Оба наблюдения сохранены. Важна не только сумма рублей, но и то, сколько на них можно купить.';renderActivity(true);
    }
    else if(action==='quiz-next')quizNext();
    else if(action==='quiz-finish'){closeDialog();navigate('results');}
    else if(action==='check-risk')checkRisk();
    else if(action==='safe-decision'){if(securityResult&&!securityResult.handled){securityResult.handled=true;state.safeDecisions++;record('safe_decision',scenarios[securityScenario].label);el.disabled=true;el.textContent='Учебное решение сохранено';toast('Решение зафиксировано в журнале');}}
    else if(action==='shift-payment')applyBusinessScenario('shift');
    else if(action==='delay-receipt')applyBusinessScenario('delay');
    else if(action==='business-revert'){businessDraft=clone(state.business);render();toast('Восстановлен сохранённый календарь');}
    else if(action==='business-example'){businessDraft=F.defaultState().business;render();toast('Исходный пример на экране. Сохраните, если хотите оставить его.');}
    else if(action==='export')exportJson();
    else if(action==='export-csv')exportCsv();
    else if(action==='import')$('#import-file').click();
    else if(action==='reset')openDialog(dialogHead('Вернуть учебный пример?')+'<div class="dialog-body"><p>Сохранённые планы, прогресс и журнал в этом браузере будут удалены. Если хотите их оставить, сначала скачайте JSON-отчёт.</p></div><div class="dialog-footer"><button class="button button-outline" data-action="close">Отмена</button><button class="button button-danger" data-action="reset-confirm">Сбросить данные</button></div>');
    else if(action==='reset-confirm'){state=F.defaultState();businessDraft=clone(state.business);securityResult=null;lessonFilter='all';persist();closeDialog();navigate('overview');toast('Открыт исходный учебный пример');}
  });
  document.addEventListener('input',event=>{
    if(event.target.dataset.priceParam&&quiz?.activity&&lessons[quiz.id].activity==='prices'){
      const key=event.target.dataset.priceParam;quiz.activity[key]=Number(event.target.value);$('#price-'+key+'-value').textContent=event.target.value+' '+(key==='years'?'':'%');$('#price-results').innerHTML=priceResults(quiz.activity);return;
    }
    if(event.target.closest('#budget-form')){try{const p=readBudget();$('#budget-result').innerHTML=budgetResult(p);$('#budget-error').textContent='';$('#budget-dirty').textContent='Есть несохранённые изменения';}catch(e){$('#budget-error').textContent='Заполните все поля корректными суммами. Расчёт обновится после исправления.';}}
    if(event.target.closest('#business-form')){try{updateBusiness();}catch(e){$('#business-error').textContent=e.message;}}
    if(event.target.closest('.risk-options')||event.target.id==='transfer-amount'||event.target.id==='recipient'){securityResult=null;if($('#risk-result'))$('#risk-result').innerHTML='<div class="empty-state"><h3>Условия изменились</h3><p class="explanation">Нажмите «Разобрать признаки», чтобы обновить результат.</p></div>';}
  });
  document.addEventListener('submit',event=>{if(event.target.id==='budget-form'){event.preventDefault();try{state.budget=readBudget();record('budget_saved','Остаток после накоплений: '+rub(F.budget(state.budget).available));$('#budget-dirty').textContent='План сохранён';toast('Личный план сохранён');}catch(e){$('#budget-error').textContent=e.message;}}if(event.target.id==='business-form'){event.preventDefault();try{if(!updateBusiness())return;state.business=clone(businessDraft);record('business_saved','Минимальный остаток: '+rub(F.forecast(state.business).min));render();toast('Календарь сохранён');}catch(e){$('#business-error').textContent=e.message;}}});
  $('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Файл слишком большой. Максимум 2 МБ.');const imported=F.validateState(JSON.parse(await file.text()));state=imported;businessDraft=clone(state.business);record('data_imported','Восстановлено из JSON');navigate(route);toast('План и прогресс восстановлены');}catch(e){toast('Не удалось восстановить: '+e.message);}finally{event.target.value='';}});
  dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
  dialog.addEventListener('cancel',()=>{quiz=null;});
  window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
  window.addEventListener('resize',()=>{const small=window.matchMedia('(max-width:740px)').matches;$('#nav').querySelectorAll('.desktop-label').forEach((el,i)=>el.textContent=small?routes[i].short:routes[i].label);});
  persist();navigate(location.hash.slice(1)||'overview',false);
  if(storageWarning)setTimeout(()=>toast(storageWarning),300);
  if(!storageAvailable)setTimeout(()=>toast('Браузер ограничил хранение. Скачайте JSON, чтобы сохранить работу.'),500);
})();
